		body: JSON.stringify({
			model,
			messages,
			stream: false,
			...(options.maxTokens ? { max_tokens: options.maxTokens } : {}),
		}),
		signal: options.signal,
	});

	if (!res.ok) {
		const text = await res.text().catch(() => "");
		throw new Error(`Perplexity API ${res.status}: ${text || res.statusText}`);
